#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

using ll = long long;

const int MAXN = 200100;

vector<int> g[MAXN];
vector<int> comp[2];
bool used[MAXN];
int ct[MAXN];

void dfs(int start, int id)
{
    if (used[start])
        return;

    vector<int> st;
    st.push_back(start);
    used[start] = true;

    while (!st.empty())
    {
        int v = st.back();
        st.pop_back();
        comp[id].push_back(v);

        for (int to : g[v])
        {
            if (!used[to])
            {
                used[to] = true;
                st.push_back(to);
            }
        }
    }
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--)
    {
        int n, m, a, b;
        cin >> n >> m >> a >> b;
        --a;
        --b;

        comp[0].clear();
        comp[1].clear();

        for (int i = 0; i < m; ++i)
        {
            int u, v;
            cin >> u >> v;
            --u;
            --v;
            g[u].push_back(v);
            g[v].push_back(u);
        }

        used[b] = true;
        dfs(a, 0);

        for (int v : comp[0])
            used[v] = false;
        used[b] = false;

        used[a] = true;
        dfs(b, 1);

        for (int i = 0; i < 2; ++i)
            for (int v : comp[i])
                ++ct[v];

        ll countA = -1;
        ll countB = -1;

        for (int v : comp[0])
            if (ct[v] == 1)
                ++countA;

        for (int v : comp[1])
            if (ct[v] == 1)
                ++countB;

        cout << max(0LL, countA * countB) << '\n';

        for (int i = 0; i < n; ++i)
        {
            g[i].clear();
            used[i] = false;
            ct[i] = 0;
        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <stack>
using namespace std;

using ll = long long;

vector<char> reachable(const vector<vector<int>>& graph, int start, int blocked) {
    vector<char> visited(graph.size(), false);
    stack<int> st;

    visited[blocked] = true;
    visited[start] = true;
    st.push(start);

    while (!st.empty()) {
        int v = st.top();
        st.pop();

        for (int to : graph[v]) {
            if (!visited[to]) {
                visited[to] = true;
                st.push(to);
            }
        }
    }

    visited[blocked] = false;
    return visited;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n, m, a, b;
        cin >> n >> m >> a >> b;
        --a;
        --b;

        vector<vector<int>> graph(n);

        for (int i = 0; i < m; ++i) {
            int u, v;
            cin >> u >> v;
            --u;
            --v;
            graph[u].push_back(v);
            graph[v].push_back(u);
        }

        vector<char> fromA = reachable(graph, a, b);
        vector<char> fromB = reachable(graph, b, a);

        ll onlyA = 0;
        ll onlyB = 0;

        for (int i = 0; i < n; ++i) {
            if (i != a && fromA[i] && !fromB[i])
                ++onlyA;
            if (i != b && fromB[i] && !fromA[i])
                ++onlyB;
        }

        cout << onlyA * onlyB << '\n';
    }

    return 0;
}

